"""Optional inference-only group mixture of first-frame R0 probabilities.

All history and target cells are jointly translated on the spatial torus.
For an autoregressive predictor each component uses its own valid raster
factorization. Mix JOINT frame probabilities, never permuted per-cell
conditional logits. This is not a change to R0 training or its baseline.
"""
import math
import torch
import torch.nn.functional as F
from .art_vanilla import ArtVanilla
from .arcnn import ARCNN


def shifts_for(grid, stride=1):
    """The translation subgroup generated by a stride dividing grid."""
    if not isinstance(grid, int) or not isinstance(stride, int) or grid < 1 or stride < 1 or grid % stride:
        raise ValueError("positive stride must divide grid")
    return tuple((r, c) for r in range(0, grid, stride) for c in range(0, grid, stride))


def _validate(model, history, target=None):
    g = model.grid
    if history.ndim != 4 or history.shape[1:] != (8, g, g) or not len(history):
        raise ValueError("history must be (B,8,H,W), nonempty, in {-1,+1}")
    if not bool(((history == -1) | (history == 1)).all()):
        raise ValueError("history must be in {-1,+1}")
    if target is not None and (target.shape != (len(history), g, g)
            or not bool(((target == 0) | (target == 1)).all())):
        raise ValueError("target must be (B,H,W) in {0,1}")
    if model.training:
        raise ValueError("use eval mode")
    if not isinstance(model, (ArtVanilla, ARCNN)):
        raise TypeError("expected original R0 predictor")
    if isinstance(model, ArtVanilla) and (model.tokenizer != "cell" or model.pos_enc != "learned"):
        raise ValueError("expected raw-cell learned-position R0")


def _frame_logits(model, history, target):
    if isinstance(model, ARCNN):
        return model._step(torch.cat((history, history[:, -1:]), 1))
    g = model.grid
    n = 8*g*g
    # Only prefix and strictly earlier raster target bits enter this model.
    tok = torch.cat((((history+1)/2).long().flatten(1), target.long().flatten(1)[:, :-1]), 1)
    return model.head(model._encode(tok)).squeeze(-1)[:, n-1:n+g*g-1].reshape(-1, g, g)


@torch.no_grad()
def component_log_probs(model, history, target, stride=1):
    """(B,K) log q(gY|gX), in nats, K spatial translations."""
    _validate(model, history, target)
    out = []
    for shift in shifts_for(model.grid, stride):
        x = torch.roll(history, shift, (-2,-1))
        y = torch.roll(target, shift, (-2,-1))
        z = _frame_logits(model, x, y)
        # Stable joint probability, regardless of raster ordering.
        dtype = torch.float32 if z.device.type == "mps" else torch.float64
        out.append(-F.binary_cross_entropy_with_logits(z, y.to(z.dtype), reduction="none").to(dtype).sum((1,2)))
    return torch.stack(out, 1)


@torch.no_grad()
def mixture_log_prob(model, history, target, stride=1):
    """Normalized joint log probability of the uniform subgroup mixture."""
    components = component_log_probs(model, history, target, stride)
    return torch.logsumexp(components, 1)-math.log(components.shape[1])


@torch.no_grad()
def sample_next_frame(model, history, stride=1, generator=None):
    """Sample a translation per world, then a complete frame, undoing shift.

    Sampling the same component for every cell preserves its joint law.
    Uses no true target or future data. The optional generator must match
    the tensor device. The raw AR path is deliberately simple, not cached.
    """
    _validate(model, history)
    shifts = shifts_for(model.grid, stride)
    b, _, g, _ = history.shape
    indices = torch.randint(len(shifts), (b,), device=history.device, generator=generator)
    x = torch.stack([torch.roll(history[i], shifts[int(indices[i])], (-2,-1)) for i in range(b)])
    if isinstance(model, ARCNN):
        prob = model._step(torch.cat((x, x[:, -1:]),1)).sigmoid()
        result = torch.rand(prob.shape, device=prob.device, generator=generator) < prob
    else:
        tokens = ((x+1)/2).long().flatten(1)
        for _ in range(g*g):
            prob = model.head(model._encode(tokens)[:, -1]).squeeze(-1).sigmoid()
            new = (torch.rand(prob.shape, device=prob.device, generator=generator) < prob).long()
            tokens = torch.cat((tokens,new[:,None]),1)
        result = tokens[:, -g*g:].reshape(b,g,g).bool()
    return torch.stack([torch.roll(result[i], tuple(-s for s in shifts[int(indices[i])]), (-2,-1)) for i in range(b)]).to(torch.uint8)


@torch.no_grad()
def rollout_sample(model, history, steps=8, stride=1, generator=None):
    """Autonomous sliding-window generation; no teacher forcing."""
    if not isinstance(steps,int) or steps < 1:
        raise ValueError("positive steps required")
    pred=[]
    for _ in range(steps):
        y=sample_next_frame(model,history,stride,generator)
        pred.append(y)
        history=torch.cat((history[:,1:], (2*y.to(history.dtype)-1)[:,None]),1)
    return torch.stack(pred,1)
